// Generated by GitHub Copilot
/**
 * Secure channel primitives for BLE Pay (protocol v1).
 *
 *  - ECDH P-256 ephemeral key agreement (forward secrecy per session).
 *  - HKDF-SHA256 with `salt = handshakeSalt || PIN` to bind the channel to the
 *    out-of-band PIN shown on the receiver side. An attacker without the PIN
 *    cannot derive the same AES-GCM key, so MITM substitution of public keys
 *    is detected when authenticated decryption fails.
 *  - AES-GCM-256 for AEAD encryption of every message after the handshake.
 *
 * Threat model notes (prototype):
 *  - Confidentiality: passive eavesdroppers see only public keys + ciphertext.
 *  - Integrity / authentication: AES-GCM tag fails on tampering or wrong key.
 *  - MITM resistance: relies on the PIN entropy. With a 6-digit PIN (~20 bits)
 *    a captured handshake is brute-forceable offline. For production use a
 *    real PAKE (SPAKE2) or a longer secret. Documented limitation.
 */

const TE = new TextEncoder();
const TD = new TextDecoder('utf-8', { fatal: true });

export interface KeyPair {
  publicKey: CryptoKey;
  privateKey: CryptoKey;
}

/** Generate an ephemeral ECDH P-256 key pair. */
export async function generateEphemeralKeyPair(): Promise<KeyPair> {
  const kp = await crypto.subtle.generateKey(
    { name: 'ECDH', namedCurve: 'P-256' },
    true,
    ['deriveKey', 'deriveBits']
  );
  return { publicKey: kp.publicKey, privateKey: kp.privateKey };
}

/** Export a P-256 public key to its 65-byte uncompressed raw form. */
export async function exportPubRaw(pub: CryptoKey): Promise<Uint8Array> {
  const buf = await crypto.subtle.exportKey('raw', pub);
  return new Uint8Array(buf);
}

/** Import a 65-byte raw P-256 public key. */
export async function importPubRaw(bytes: Uint8Array): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    bytes as Uint8Array<ArrayBuffer>,
    { name: 'ECDH', namedCurve: 'P-256' },
    true,
    []
  );
}

/**
 * Derive the AES-GCM session key from ECDH + handshake salt + PIN.
 * Both peers must call this with the same (salt, PIN) and matching key pair to
 * obtain the same key.
 */
export async function deriveSessionKey(
  myPriv: CryptoKey,
  peerPub: CryptoKey,
  handshakeSalt: Uint8Array,
  pinDigits: string
): Promise<CryptoKey> {
  if (!/^\d{4,12}$/.test(pinDigits)) {
    throw new Error('PIN inválido (4–12 dígitos).');
  }
  const sharedBits = await crypto.subtle.deriveBits(
    { name: 'ECDH', public: peerPub },
    myPriv,
    256
  );
  const hkdfBase = await crypto.subtle.importKey(
    'raw',
    sharedBits,
    'HKDF',
    false,
    ['deriveKey']
  );
  const pinBytes = TE.encode(pinDigits);
  const fullSalt = new Uint8Array(handshakeSalt.byteLength + pinBytes.byteLength);
  fullSalt.set(handshakeSalt, 0);
  fullSalt.set(pinBytes, handshakeSalt.byteLength);
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: fullSalt,
      info: TE.encode('ble-pay-v1-aead')
    },
    hkdfBase,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

/** AES-GCM encrypt with a fresh 12-byte random IV. */
export async function aesGcmEncrypt(
  key: CryptoKey,
  plaintext: Uint8Array
): Promise<{ iv: Uint8Array; ct: Uint8Array }> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(
    await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext as Uint8Array<ArrayBuffer>)
  );
  return { iv, ct };
}

/** AES-GCM decrypt. Throws if the auth tag does not verify. */
export async function aesGcmDecrypt(
  key: CryptoKey,
  iv: Uint8Array,
  ct: Uint8Array
): Promise<Uint8Array> {
  return new Uint8Array(
    await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ct as Uint8Array<ArrayBuffer>)
  );
}

/** Generate a uniform N-digit PIN using crypto.getRandomValues + rejection. */
export function generatePin(digits = 6): string {
  if (digits < 4 || digits > 9) throw new Error('digits fuera de rango');
  const max = 10 ** digits;
  const limit = Math.floor(0xffffffff / max) * max;
  const buf = new Uint32Array(1);
  for (;;) {
    crypto.getRandomValues(buf);
    if (buf[0] < limit) {
      return (buf[0] % max).toString().padStart(digits, '0');
    }
  }
}

/** Random salt for the handshake KDF. */
export function generateSalt(bytes = 16): Uint8Array {
  return crypto.getRandomValues(new Uint8Array(bytes));
}

export function b64encode(bytes: Uint8Array): string {
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}
export function b64decode(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// ---- Wire envelopes (protocol v1) -----------------------------------------

/** Hello — receiver → payer. Carries the receiver pubkey and handshake salt. */
export interface SecureHello {
  v: 1;
  kind: 'hello';
  receiver_pub: string; // base64(raw P-256, 65 bytes)
  salt: string;         // base64
  ts: number;
}

/** Hello-ack — payer → receiver. Carries payer pubkey + AEAD probe. */
export interface SecureHelloAck {
  v: 1;
  kind: 'hello_ack';
  payer_pub: string; // base64
  iv: string;        // base64 (12 bytes)
  ct: string;        // base64; plaintext == HELLO_PROBE
}

/** Encrypted intent — receiver → payer (after key derivation). */
export interface SecureIntentEnv {
  v: 1;
  kind: 'sec_intent';
  iv: string;
  ct: string; // ciphertext of the canonical PaymentIntent JSON
}

/** Encrypted ack — payer → receiver. */
export interface SecureAckEnv {
  v: 1;
  kind: 'sec_ack';
  iv: string;
  ct: string; // ciphertext of the canonical Ack JSON
}

/**
 * Buyer confirm — payer → receiver, sent automatically when the payer sees the
 * intent and before the final ack. Lets the vendor display "Comprador confirma $Y"
 * without any extra action from either party (~200ms BLE round-trip).
 */
export interface SecureBuyerConfirm {
  v: 1;
  kind: 'buyer_confirm';
  iv: string;
  ct: string; // ciphertext of BuyerConfirmPayload
}

/** Plaintext inside a SecureBuyerConfirm. */
export interface BuyerConfirmPayload {
  tx_id: string;
  amount: number;
  currency: string;
  ts: number;
}

export type SecureEnvelope =
  | SecureHello
  | SecureHelloAck
  | SecureIntentEnv
  | SecureAckEnv
  | SecureBuyerConfirm;

/** Plaintext probe value used inside hello_ack to authenticate the channel. */
export const HELLO_PROBE = 'BLEPAY-HELLO-V1';

/** Encode any secure envelope as UTF-8 JSON bytes. */
export function encodeSecureEnvelope(env: SecureEnvelope): Uint8Array {
  return TE.encode(JSON.stringify(env));
}

/** Decode and minimally validate a secure envelope. */
export function decodeSecureEnvelope(bytes: Uint8Array): SecureEnvelope {
  if (bytes.byteLength === 0) throw new Error('Payload vacío.');
  const safe = new Uint8Array(bytes.byteLength);
  safe.set(bytes);
  let text: string;
  try {
    text = TD.decode(safe);
  } catch {
    throw new Error('Payload no es UTF-8 válido.');
  }
  const obj = JSON.parse(text) as Record<string, unknown>;
  if (obj.v !== 1) throw new Error(`Versión secure no soportada: ${String(obj.v)}`);
  const kind = obj.kind;
  if (kind !== 'hello' && kind !== 'hello_ack' && kind !== 'sec_intent' && kind !== 'sec_ack' && kind !== 'buyer_confirm') {
    throw new Error(`kind inválido: ${String(kind)}`);
  }
  return obj as unknown as SecureEnvelope;
}
